oot:not(.dark) .cm-labelName {\n  color: #0070c1 !important;\n}\n\n:root:not(.dark) .cm-number {\n  color: #098658 !important;\n}\n\n:root:not(.dark) .cm-string {\n  color: #a31515 !important;\n}\n\n:root:not(.dark) .cm-comment {\n  color: #008000 !important;\n}\n\n:root:not(.dark) .cm-meta {\n  color: #0000ff !important;\n}\n\n:root:not(.dark) .cm-variableName {\n  color: #795e26 !important;\n}\n\n/* Command palette styling */\n.command-palette {\n  @apply fixed top-16 left-1/2 transform -translate-x-1/2 w-full max-w-2xl bg-white dark:bg-gray-800 rounded-xl shadow-lg z-50 overflow-hidden;\n}\n\n.command-palette-input {\n  @apply w-full px-4 py-3 border-b border-gray-200 dark:border-gray-700 focus:outline-none;\n}\n\n.command-palette-results {\n  @apply max-h-96 overflow-y-auto;\n}\n\n.command-palette-item {\n  @apply px-4 py-2 hover:bg-gray-100 dark:hover:bg-gray-700 cursor-pointer flex items-center;\n}\n\n.command-palette-item.active {\n  @apply bg-gray-100 dark:bg-gray-700;\n}\n\n/* Tooltip styling for hover information */\n.tooltip {\n  @apply absolute z-10 p-2 bg-white dark:bg-gray-800 text-gray-800 dark:text-white text-sm rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 max-w-xs;\n}\n\n/* Diagnostic styling for error/warning/info */\n.diagnostic {\n  @apply relative;\n}\n\n.diagnostic-error {\n  @apply border-b-2 border-red-500;\n}\n\n.diagnostic-warning {\n  @apply border-b-2 border-yellow-500;\n}\n\n.diagnostic-info {\n  @apply border-b-2 border-blue-500;\n}\n\n.diagnostic-message {\n  @apply absolute z-10 p-2 bg-white dark:bg-gray-800 text-gray-800 dark:text-white text-sm rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 max-w-xs;\n}\n\n/* Visualizer specific styles */\n.visualizer-container {\n  @apply w-full h-full bg-gray-900;\n}\n\n/* Stack visualization styles */\n.stack-item {\n  @apply px-4 py-2 border border-gray-700 bg-gray-800 text-white;\n}\n\n/* Memory panel styles */\n.memory-cell {\n  @apply px-2 py-1 text-xs fon