import React from 'react';
import { motion } from 'framer-motion';

/**
 * Execution control panel with responsive step controls
 */
function ExecutionControls({ onStep, onReset, onGetCorrectOutput, isRunning, isDarkMode, compact = false }) {
  const handleStep = (direction) => {
    onStep(direction);
  };

  const handleRunStop = () => {
    if (isRunning) {
      onStep('stop');
    } else {
      onStep('run');
    }
  };

  // Button configuration for easy customization
  const buttons = [
    {
      label: compact ? '' : 'Step Back',
      icon: 'fas fa-step-backward',
      onClick: () => handleStep(-1),
      disabled: isRunning,
      className: isRunning 
        ? 'bg-gray-300 text-gray-500 cursor-not-allowed' 
        : 'bg-orange-500 hover:bg-orange-600 text-white'
    },
    {
      label: compact ? '' : 'Step Forward',
      icon: 'fas fa-step-forward',
      onClick: () => handleStep(1),
      disabled: isRunning,
      className: isRunning 
        ? 'bg-gray-300 text-gray-500 cursor-not-allowed' 
        : 'bg-green-500 hover:bg-green-600 text-white'
    },
    {
      label: compact ? '' : (isRunning ? 'Stop' : 'Run'),
      icon: `fas fa-${isRunning ? 'stop' : 'play'}`,
      onClick: handleRunStop,
      disabled: false,
      className: isRunning 
        ? 'bg-red-500 hover:bg-red-600 text-white' 
        : 'bg-blue-500 hover:bg-blue-600 text-white'
    },
    {
      label: compact ? '' : 'Reset',
      icon: 'fas fa-redo',
      onClick: onReset,
      disabled: isRunning,
      className: isRunning 
        ? 'bg-gray-300 text-gray-500 cursor-not-allowed' 
        : isDarkMode 
          ? 'bg-gray-700 hover:bg-gray-600 text-white'
          : 'bg-gray-200 hover:bg-gray-300 text-gray-800'
    },
    ...(onGetCorrectOutput ? [{
      label: compact ? '' : 'Correct Output',
      icon: 'fas fa-check-circle',
      onClick: onGetCorrectOutput,
      disabled: isRunning,
      className: isRunning 
        ? 'bg-gray-300 text-gray-500 cursor-not-allowed' 
        : 'bg-green-500 hover:bg-green-600 text-white'
    }] : [])
  ];

  return (
    <motion.div 
      className={`h-full flex items-center ${
        isDarkMode ? 'bg-gray-800' : 'bg-white'
      }`}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: 0.3 }}
    >
      <div className="w-full px-2">
        <div className={`flex items-center ${compact ? 'justify-center' : 'justify-center'} gap-1 flex-wrap`}>
          {buttons.map((button, index) => (
            <button
              key={index}
              onClick={button.onClick}
              disabled={button.disabled}
              className={`
                ${compact ? 'p-2 min-w-[2.5rem]' : 'px-3 py-2'} 
                rounded-lg font-medium transition-colors flex items-center justify-center gap-2
                ${button.className}
                ${compact ? 'text-sm' : 'text-sm'}
                focus:outline-none focus:ring-2 focus:ring-opacity-50
                ${!button.disabled ? 'focus:ring-blue-300' : ''}
              `}
            >
              <i className={`${button.icon} ${compact ? 'text-base' : 'text-sm'}`}></i>
              {button.label && <span className="whitespace-nowrap">{button.label}</span>}
            </button>
          ))}
        </div>
      </div>
    </motion.div>
  );
}

export default ExecutionControls;